import{_ as a,o as s,c as e,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"虚拟化与容器: VM / KVM / namespaces / gVisor","description":"","frontmatter":{},"headers":[],"relativePath":"os/virtualization.md","filePath":"os/virtualization.md","lastUpdated":1788475713000}'),r={name:"os/virtualization.md"};function n(i,t,d,l,p,c){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="虚拟化与容器-vm-kvm-namespaces-gvisor" tabindex="-1">虚拟化与容器: VM / KVM / namespaces / gVisor <a class="header-anchor" href="#虚拟化与容器-vm-kvm-namespaces-gvisor" aria-label="Permalink to &quot;虚拟化与容器: VM / KVM / namespaces / gVisor&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>&quot;一台物理机跑多个隔离的 OS&quot;和&quot;一个内核跑多个隔离的应用&quot;是两个不同的问题。<strong>虚拟机</strong>（VM）用 hypervisor 虚拟出完整硬件（CPU/内存/设备），客户机里跑独立内核；<strong>容器</strong>不虚拟硬件，只复用宿主机内核 + 用 <strong>namespaces</strong> 隔离视图 + <strong>cgroups</strong> 限制资源。这一章把 KVM 的 CPU/内存虚拟化原理（VT-x、EPT）、设备虚拟化（virtio、SR-IOV）、容器的隔离边界（为什么 namespaces 挡不住内核漏洞）、以及 gVisor/Kata/Firecracker 这些&quot;安全容器&quot;的取舍讲透。</p><p>读完应能：</p><ol><li>说清 trap-and-emulate 为什么行不通，VT-x/AMD-V 的 VMX root/non-root 模式怎么解决。</li><li>解释 EPT（二级页表）让&quot;虚拟机内存&quot;不经过软件影子页表的原理，以及为什么 EPT 下 MMIO 要特殊处理。</li><li>说出容器隔离的是&quot;视图&quot;不是&quot;资源边界&quot;：namespaces 管什么、cgroups 管什么、共享内核的逃逸面在哪。</li><li>对比 gVisor（用户态内核）vs Kata/Firecracker（微型 VM）vs 普通容器在不同威胁模型下的取舍。</li><li>在 K8s 场景说出&quot;什么时候必须上 VM 级隔离（多租户/不可信负载），什么时候容器够了（可信负载）&quot;。</li></ol><hr><h2 id="一、虚拟化要解决的三个问题" tabindex="-1">一、虚拟化要解决的三个问题 <a class="header-anchor" href="#一、虚拟化要解决的三个问题" aria-label="Permalink to &quot;一、虚拟化要解决的三个问题&quot;">​</a></h2><ol><li><strong>隔离</strong>：故障/攻击不能跨租户传播；</li><li><strong>复用</strong>：物理资源（CPU 核、内存、带宽）在多个租户间弹性分配；</li><li><strong>迁移</strong>：工作负载与硬件解耦，可热迁移。</li></ol><p>三条路线的隔离强度递减、密度递增：</p><table tabindex="0"><thead><tr><th></th><th>隔离强度</th><th>密度/开销</th><th>典型</th></tr></thead><tbody><tr><td>裸机</td><td>最强</td><td>最低</td><td>物理机独享</td></tr><tr><td>虚拟机</td><td>强（独立内核）</td><td>中（每 VM 一个内核）</td><td>云主机、Kata/Firecracker</td></tr><tr><td>容器</td><td>弱（共享内核）</td><td>高</td><td>微服务、Serverless</td></tr></tbody></table><h2 id="二、cpu-虚拟化-从-trap-and-emulate-到硬件辅助" tabindex="-1">二、CPU 虚拟化: 从 trap-and-emulate 到硬件辅助 <a class="header-anchor" href="#二、cpu-虚拟化-从-trap-and-emulate-到硬件辅助" aria-label="Permalink to &quot;二、CPU 虚拟化: 从 trap-and-emulate 到硬件辅助&quot;">​</a></h2><h3 id="_2-1-朴素思路为什么不行" tabindex="-1">2.1 朴素思路为什么不行 <a class="header-anchor" href="#_2-1-朴素思路为什么不行" aria-label="Permalink to &quot;2.1 朴素思路为什么不行&quot;">​</a></h3><p>让客户 OS 直接跑在 CPU 上，遇到特权指令时陷入 hypervisor（trap-and-emulate）。问题：x86 有约 17 条<strong>敏感但不特权</strong>的指令（如 <code>POPF</code>、<code>SGDT</code>），在低特权级下不触发陷阱、行为却和裸机不同——客户 OS 会静默出错。这是 x86 虚拟化的历史难题，直到 2005-2006 年 <strong>Intel VT-x / AMD-V</strong> 在硬件上解决。</p><h3 id="_2-2-vt-x-两种模式" tabindex="-1">2.2 VT-x: 两种模式 <a class="header-anchor" href="#_2-2-vt-x-两种模式" aria-label="Permalink to &quot;2.2 VT-x: 两种模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VMX root (hypervisor 跑这里)     VMX non-root (客户 OS 跑这里)</span></span>
<span class="line"><span>        ▲                                    │</span></span>
<span class="line"><span>        │ VM exit (特权操作/中断/异常)        │</span></span>
<span class="line"><span>        └────────────────────────────────────┘</span></span>
<span class="line"><span>        VM entry (resume)</span></span></code></pre></div><ul><li>客户 OS 运行在 <strong>non-root</strong> 模式，特权操作（<code>CPUID</code>、<code>WRMSR</code>、<code>HLT</code>、访问 CR3 等）<strong>自动 VM exit</strong> 回 hypervisor；</li><li>用 <strong>VMCS（VM Control Structure）</strong> 描述每次 exit 的原因和 guest 状态，exit 后 hypervisor 处理完再 VM entry；</li><li>频繁 exit 很贵（几千 cycles），所以 KVM 会<strong>让大部分中断直接注入客户机</strong>，只有必要事件才 exit。</li></ul><h3 id="_2-3-中断虚拟化" tabindex="-1">2.3 中断虚拟化 <a class="header-anchor" href="#_2-3-中断虚拟化" aria-label="Permalink to &quot;2.3 中断虚拟化&quot;">​</a></h3><ul><li>物理中断由宿主内核收，KVM 把它<strong>注入</strong> guest（<code>vmcs</code> 的 event injection）；</li><li>APICv / posted interrupts：物理中断直接投递到正在跑 guest 的 vCPU，<strong>不 exit</strong>——这是高 IO 虚拟机的关键优化。</li></ul><h2 id="三、内存虚拟化-影子页表-→-ept" tabindex="-1">三、内存虚拟化: 影子页表 → EPT <a class="header-anchor" href="#三、内存虚拟化-影子页表-→-ept" aria-label="Permalink to &quot;三、内存虚拟化: 影子页表 → EPT&quot;">​</a></h2><p>客户机认为自己在管物理内存，但那是&quot;客户物理地址（GPA）&quot;，还要再映射到宿主的&quot;机器物理地址（HPA）&quot;。早期做法是<strong>影子页表</strong>：hypervisor 维护一份&quot;客户虚拟地址 → 宿主物理地址&quot;的页表，guest 每次改 CR3/页表都要 exit 同步——开销大、实现复杂。</p><p>硬件辅助（<strong>EPT</strong>，AMD 叫 NPT）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户虚拟地址 GVA ──guest 页表──► 客户物理地址 GPA</span></span>
<span class="line"><span>                                    └─EPT 页表──► 宿主物理地址 HPA</span></span></code></pre></div><ul><li>客户机照常管理自己的页表，<strong>不需要 exit</strong>；CPU 硬件自动走两级页表翻译；</li><li>代价是 TLB 需要同时缓存两级翻译（EPT 使 TLB miss 变贵），所以有 <code>ept</code> + <code>VPID</code>（虚拟处理器 ID，避免切换 vCPU 时刷 TLB）。</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>EPT 不是免费的：两级翻译的 TLB miss 开销比裸机高。大数据集虚拟机（如 Redis 类大页内存）要配合 <strong>HugeTLB/hugepages</strong>，否则页表遍历会吃掉可观的 CPU。</p></div><h2 id="四、设备虚拟化-全虚拟-→-virtio-→-sr-iov" tabindex="-1">四、设备虚拟化: 全虚拟 → virtio → SR-IOV <a class="header-anchor" href="#四、设备虚拟化-全虚拟-→-virtio-→-sr-iov" aria-label="Permalink to &quot;四、设备虚拟化: 全虚拟 → virtio → SR-IOV&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>性能</th><th>使用</th></tr></thead><tbody><tr><td><strong>软件模拟</strong>（QEMU 模拟网卡/磁盘）</td><td>每个 IO 都 exit + 模拟寄存器</td><td>低</td><td>兼容性兜底</td></tr><tr><td><strong>virtio</strong></td><td>前端驱动 + 共享环形队列，hypervisor 批量处理描述符</td><td>中高</td><td>云主机默认</td></tr><tr><td><strong>SR-IOV</strong>（VF 直通）</td><td>物理网卡切成多个虚拟功能，guest 直接 DMA</td><td>最高</td><td>高性能网络/存储</td></tr><tr><td><strong>VFIO/直通</strong>（GPU/NVMe）</td><td>整个物理设备给一个 guest</td><td>最高</td><td>GPU 透传、NFV</td></tr></tbody></table><p>virtio 的关键是<strong>减少 exit</strong>：guest 驱动把一批 IO 描述符放进共享内存的 virtqueue，hypervisor（vhost）批量消费，一次 kick 处理一批。<code>vhost</code> 把 virtqueue 处理搬进宿主内核，进一步避免每次退出用户态。</p><h2 id="五、容器-不是虚拟化-是-切视图" tabindex="-1">五、容器: 不是虚拟化，是&quot;切视图&quot; <a class="header-anchor" href="#五、容器-不是虚拟化-是-切视图" aria-label="Permalink to &quot;五、容器: 不是虚拟化，是&quot;切视图&quot;&quot;">​</a></h2><p>容器共享宿主内核，靠两套内核机制：</p><h3 id="_5-1-namespaces-隔离-我看到什么" tabindex="-1">5.1 namespaces: 隔离&quot;我看到什么&quot; <a class="header-anchor" href="#_5-1-namespaces-隔离-我看到什么" aria-label="Permalink to &quot;5.1 namespaces: 隔离&quot;我看到什么&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>namespace</th><th>隔离内容</th><th>安全含义</th></tr></thead><tbody><tr><td>PID</td><td>进程号（容器内 PID 1 = 容器主进程）</td><td>看不到其他容器的进程</td></tr><tr><td>Mount</td><td>挂载点视图</td><td>配合 chroot/pivot_root 限制文件系统</td></tr><tr><td>Network</td><td>网卡/IP/路由/防火墙</td><td>每个容器独立网络栈</td></tr><tr><td>UTS</td><td>hostname</td><td>—</td></tr><tr><td>IPC</td><td>SysV/Posix 消息队列</td><td>—</td></tr><tr><td>User</td><td>UID/GID 映射（root 在容器内 ≠ 宿主 root）</td><td>非特权容器关键</td></tr><tr><td>Cgroup</td><td>资源视图（<code>/sys/fs/cgroup</code> 只读呈现自己）</td><td>—</td></tr></tbody></table><h3 id="_5-2-cgroups-限制-我能用多少" tabindex="-1">5.2 cgroups: 限制&quot;我能用多少&quot; <a class="header-anchor" href="#_5-2-cgroups-限制-我能用多少" aria-label="Permalink to &quot;5.2 cgroups: 限制&quot;我能用多少&quot;&quot;">​</a></h3><p>v2 的控制器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cpu.max     = 配额 (比如 2 核 / 4 核共享)</span></span>
<span class="line"><span>memory.max  = 内存上限 (超限 OOM-kill 容器内进程)</span></span>
<span class="line"><span>io.max      = 磁盘带宽/IOPS</span></span>
<span class="line"><span>pids.max    = 进程数</span></span></code></pre></div><h3 id="_5-3-隔离-安全边界" tabindex="-1">5.3 隔离 ≠ 安全边界 <a class="header-anchor" href="#_5-3-隔离-安全边界" aria-label="Permalink to &quot;5.3 隔离 ≠ 安全边界&quot;">​</a></h3><p>namespaces/cgroups 是<strong>内核对象视图的分隔</strong>，不是内核自身的安全边界：</p><ul><li>容器内 <code>unshare</code>/mount 操作仍受宿主内核控制，<strong>内核漏洞（如 Dirty Pipe、OverlayFS 提权）可跨容器</strong>；</li><li>共享宿主内核 = 共享崩溃域：宿主 OOM 可能波及所有容器；</li><li>特权容器（<code>--privileged</code>、挂载 <code>/proc</code>、宿主机 PID namespace）等于放弃隔离。</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>容器默认的 root 在 User namespace 未启用时就是宿主 UID 0（只是视野受限）。<strong>多租户场景绝不能用普通 Docker 容器承载不可信代码</strong>；单租户/可信负载（自己的微服务）容器隔离足够，这是云厂商与自用 K8s 的分水岭。</p></div><h2 id="六、安全容器-把-vm-的隔离拿回来" tabindex="-1">六、安全容器: 把 VM 的隔离拿回来 <a class="header-anchor" href="#六、安全容器-把-vm-的隔离拿回来" aria-label="Permalink to &quot;六、安全容器: 把 VM 的隔离拿回来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>代价</th><th>场景</th></tr></thead><tbody><tr><td><strong>gVisor</strong>（Google）</td><td>在用户态实现一个&quot;应用内核&quot;（Sentry），系统调用被拦截翻译</td><td>兼容性差（部分 syscall 不支持）、性能损耗</td><td>不可信但偏 CPU 的代码</td></tr><tr><td><strong>Kata Containers</strong></td><td>每个容器 = 一个微型 VM（QEMU/cloud-hypervisor + 轻量内核）</td><td>VM 开销、启动慢</td><td>多租户强隔离</td></tr><tr><td><strong>Firecracker</strong>（AWS）</td><td>极简微 VM，砍掉 BIOS/ACPI，内存 5MB 起</td><td>设备支持少</td><td>Lambda/Fargate 的沙箱底座</td></tr></tbody></table><p>选型逻辑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可信负载(自研微服务)        → 普通容器 (namespaces+cgroups)</span></span>
<span class="line"><span>半可信(第三方二进制/插件)    → gVisor 或 Kata</span></span>
<span class="line"><span>不可信(多租户代码/公共函数)  → Firecracker/Kata + 严格网络策略</span></span></code></pre></div><h2 id="七、云上工程实践" tabindex="-1">七、云上工程实践 <a class="header-anchor" href="#七、云上工程实践" aria-label="Permalink to &quot;七、云上工程实践&quot;">​</a></h2><ul><li><strong>KVM + QEMU 是 Linux 虚拟化事实标准</strong>；libvirt/OpenStack 之上，云厂商再套一层 SR-IOV/DPDK 网络；</li><li>K8s 运行时三层：<code>runc</code>（普通容器）→ <code>containerd-shim</code>（Kata）→ Firecracker（Fargate 类）；</li><li>热迁移的前提是<strong>共享存储 + CPU 特性掩码一致</strong>（否则迁移后 CPU 指令集漂移崩溃）；</li><li>超卖纪律：<code>memory</code> 超卖会触发宿主 swap/OOM 抖动，CPU 超卖要配 cgroup 配额而非放任抢；</li><li>排查顺序：guest 慢先看 <strong>steal time</strong>（<code>/proc/stat</code> 的 st），宿主 CPU 争抢直接体现在 st 上——这是&quot;云上延迟毛刺&quot;的第一现场。</li></ul><h2 id="八、一页速查" tabindex="-1">八、一页速查 <a class="header-anchor" href="#八、一页速查" aria-label="Permalink to &quot;八、一页速查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VM:     独立内核, hypervisor 虚拟 CPU(VMCS)/内存(EPT)/设备(virtio,SR-IOV)</span></span>
<span class="line"><span>KVM:    内核态 hypervisor, 客户 OS = non-root 模式, 中断注入/APICv</span></span>
<span class="line"><span>容器:   namespaces(视图) + cgroups(资源), 共享内核 → 不是安全边界</span></span>
<span class="line"><span>逃逸面: 内核漏洞 / 特权容器 / 共享崩溃域</span></span>
<span class="line"><span>安全容器: gVisor(用户态内核) / Kata(微型VM) / Firecracker(微VM)</span></span>
<span class="line"><span>运维:    steal time 查宿主争抢 / 大页配 EPT / 热迁移要特征掩码一致</span></span></code></pre></div><p>下一篇: <a href="./lock/">锁与同步原语</a>。</p>`,47)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
